package fft

// dct4Fused64Route is true where the fused DCT-IV(64) beat the pooled path
// (Apple M4 Max: 88 ns to 44 ns, go-fft/fft#132); amd64 keeps its AVX2 kernels.
const dct4Fused64Route = true

// dct4PairRoute: the NEON pair kernels run on every arm64 CPU.
func dct4PairRoute() bool { return true }

// The NEON pair kernels (dct4_64_arm64.s, generated by internal/gendct4): two
// DCT-IV(64) in the two lanes of every vector register, so each instruction does
// both transforms. They read all 64 inputs of both streams before the first
// store; dst0 may alias src0 and dst1 may alias src1 but no other overlap is
// allowed (runPair checks). They spill to their own stack frame.

//go:noescape
func dct4n64PairF64(dst0, dst1, src0, src1 *float64, w *dct4n64VTab)

//go:noescape
func dct4n64PairF64S(dst0, dst1, src0, src1 *float64, w *dct4n64VTab, f float64)

//go:noescape
func dct4n64PairF32(dst0, dst1, src0, src1 *float32, w *dct4n64VTab)

//go:noescape
func dct4n64PairF32S(dst0, dst1, src0, src1 *float32, w *dct4n64VTab, f float64)

func dct4Pair64(dst0, dst1, src0, src1 []float64, f float64) {
	if f != 1 {
		dct4n64PairF64S(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n64V, f)
	} else {
		dct4n64PairF64(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n64V)
	}
}

func dct4Pair64Mixed(dst0, dst1, src0, src1 []float32, f float64) {
	if f != 1 {
		dct4n64PairF32S(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n64V, f)
	} else {
		dct4n64PairF32(&dst0[0], &dst1[0], &src0[0], &src1[0], &dct4n64V)
	}
}
